using Astronomy.MediaFactory.Core.DocumentaryBlueprint;
namespace Astronomy.MediaFactory.Tests.DocumentaryBlueprint; public sealed class DocumentaryMediaProjectionVisualTests { [Fact] public void Visual_prompts_are_logical_fact_derived_instructions_only(){var p=DocumentaryMediaProjectionFixture.Complete(DocumentaryMediaProjectionFixture.Orion());foreach(var v in p.Variants.SelectMany(x=>x.Scenes).SelectMany(x=>x.VisualPrompts)){Assert.Equal(0,v.Sequence);Assert.StartsWith("Accurate ",v.PromptEnglish);Assert.False(string.IsNullOrWhiteSpace(v.PromptHindi!));Assert.Empty(v.NegativePrompt);Assert.NotEmpty(v.SubjectIds);Assert.NotEmpty(v.KnowledgeReferences);Assert.DoesNotContain("http",v.PromptEnglish,StringComparison.OrdinalIgnoreCase);}} }
